export function installFontPicker({library,select,onChange}){
 const button=document.createElement('button');button.id='font-picker-button';button.type='button';button.setAttribute('aria-haspopup','dialog');button.textContent='Arimo';select.hidden=true;select.tabIndex=-1;select.after(button);
 const dialog=document.createElement('dialog');dialog.id='font-picker';dialog.setAttribute('aria-labelledby','font-picker-title');
 dialog.innerHTML=`<div class="font-picker-heading"><h2 id="font-picker-title">Choose a font</h2><button type="button" id="font-picker-close" aria-label="Close font picker">×</button></div><label class="font-search-label">Search fonts<input id="font-search" type="search" placeholder="Search by name or purpose"></label><label class="font-filter-label">Show<select id="font-filter"><option value="all">All 20 fonts</option><option value="available">Available offline</option><option value="Basics">Basics</option><option value="Signs & explainers">Signs & explainers</option><option value="Chunky lettering">Chunky lettering</option><option value="Games">Games</option><option value="Fun & handwriting">Fun & handwriting</option></select></label><div id="font-results" aria-label="Font choices"></div><p id="font-picker-status" role="status"></p>`;
 document.body.append(dialog);const results=dialog.querySelector('#font-results'),status=dialog.querySelector('#font-picker-status'),search=dialog.querySelector('#font-search'),filter=dialog.querySelector('#font-filter');let fonts=[],active=0,queue=[],busy=false,generation=0;
 function sync(){const entry=library.entry(select.value),bold=document.getElementById('text-bold');bold.disabled=!!entry&&entry.normal===entry.bold;if(bold.disabled)bold.setAttribute('aria-pressed','false');button.textContent=select.selectedOptions[0]?.textContent||select.value||'Arimo';button.setAttribute('aria-label',`Choose font, ${select.value}`);button.style.fontFamily=`"${select.value}",sans-serif`;}
 const observer=new IntersectionObserver(entries=>{for(const item of entries)if(item.isIntersecting){observer.unobserve(item.target);queue.push({node:item.target,family:item.target.dataset.family,generation});}pump();},{root:results,rootMargin:'40px'});
 function pump(){while(dialog.open&&active<3&&queue.length){const task=queue.shift();if(task.generation!==generation)continue;active++;library.preview(task.family).then(name=>{if(task.node.isConnected)task.node.querySelector('.font-sample').style.fontFamily=`"${name}",sans-serif`;}).catch(()=>{}).finally(()=>{active--;pump();});}}
 function render(){generation++;queue=[];observer.disconnect();results.replaceChildren();const query=search.value.trim().toLowerCase(),mode=filter.value;
  const visible=fonts.filter(font=>(mode==='all'||mode==='available'&&library.available(font.family,document.getElementById('text-bold').getAttribute('aria-pressed')==='true',document.getElementById('text-italic').getAttribute('aria-pressed')==='true')||font.group===mode)&&`${font.family} ${font.group} ${font.description}`.toLowerCase().includes(query));
  for(const font of visible){const row=document.createElement('button');row.type='button';row.className='font-choice';row.dataset.family=font.family;row.setAttribute('aria-label',`Choose ${font.family}`);row.setAttribute('aria-pressed',String(select.value===font.family));const sample=document.createElement('span');sample.className='font-sample';sample.textContent=font.family;const detail=document.createElement('small');detail.textContent=`${font.description} · ${font.bundled?'Included':library.available(font.family,document.getElementById('text-bold').getAttribute('aria-pressed')==='true',document.getElementById('text-italic').getAttribute('aria-pressed')==='true')?'Downloaded':'Download'}`;row.append(sample,detail);row.onclick=()=>choose(font);results.append(row);observer.observe(row);}
  if(!visible.length){const empty=document.createElement('p');empty.textContent='No matching fonts.';results.append(empty);}
 }
 async function choose(font){if(busy)return;busy=true;status.textContent=library.available(font.family,document.getElementById('text-bold').getAttribute('aria-pressed')==='true',document.getElementById('text-italic').getAttribute('aria-pressed')==='true')?`Loading ${font.family}…`:`Downloading ${font.family}…`;results.setAttribute('aria-busy','true');
  try{const loaded=await library.ensure(font.family,document.getElementById('text-bold').getAttribute('aria-pressed')==='true',document.getElementById('text-italic').getAttribute('aria-pressed')==='true');if(!dialog.open)return;select.value=font.family;sync();await onChange();if(!loaded.stored){status.textContent='Font loaded for this session. Browser storage is unavailable; it will need downloading again next time.';render();}else dialog.close();}
  catch(error){status.textContent=error.message||'This font could not be loaded. Your previous font is unchanged.';}
  finally{busy=false;results.removeAttribute('aria-busy');}
 }
 select.addEventListener('change',sync);
 button.onclick=async()=>{dialog.showModal();status.textContent='Loading font list…';try{fonts=[...await library.ready].sort((a,b)=>Number(b.bundled)-Number(a.bundled)||a.family.localeCompare(b.family));status.textContent='';render();search.focus();}catch(error){status.textContent=error.message;}};
 dialog.querySelector('#font-picker-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{queue=[];observer.disconnect();});search.oninput=render;filter.onchange=render;
 library.ready.then(list=>{const current=select.value;select.replaceChildren();for(const font of list){const option=new Option(font.family,font.family);select.add(option);}select.value=list.some(font=>font.family===current)?current:'Arimo';sync();}).catch(()=>{});
 return {sync};
}
